{
  "units": [
    {
      "quote_ref": "F003",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "To receive a grant or allotment under section 9905 or 9906 of this title, the chief executive officer of a State desiring such funding must designate, in an application submitted to the Secretary under subsection (b), an appropriate State agency that complies with the duties specified in paragraph (2) to act as the lead agency for carrying out State activities under this chapter."
    },
    {
      "quote_ref": "F006",
      "scope_refs": ["F005"],
      "kind": "requirement",
      "meaning": "The designated State lead agency is required to develop the State plan to be submitted to the Secretary under subsection (b)."
    },
    {
      "quote_ref": "F007",
      "scope_refs": ["F005"],
      "kind": "requirement",
      "meaning": "In conjunction with developing the State plan as required under subsection (b), the lead agency must hold at least one public hearing in the State, providing sufficient advance time and statewide distribution of notice, to give the public an opportunity to comment on the proposed use and distribution of funds provided through the grant or allotment under section 9905 or 9906 of this title for the period covered by the plan."
    },
    {
      "quote_ref": "F008",
      "scope_refs": ["F005"],
      "kind": "requirement",
      "meaning": "The designated State lead agency is required to conduct reviews of eligible entities under section 9914 of this title."
    },
    {
      "quote_ref": "F011",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "To be eligible to receive a grant or allotment under section 9905 or 9906 of this title, the State must hold at least one legislative hearing every 3 years in conjunction with the development of the State plan."
    },
    {
      "quote_ref": "F013",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Beginning with fiscal year 2000, to be eligible to receive a grant or allotment under section 9905 or 9906 of this title, a State must prepare and submit to the Secretary an application and State plan covering a period of not less than 1 fiscal year and not more than 2 fiscal years, submitted not later than 30 days prior to the beginning of the first fiscal year covered by the plan, and containing such information as the Secretary requires, including the statutory items in subsection (b)."
    },
    {
      "quote_ref": "F015:F024",
      "scope_refs": ["F013", "F014"],
      "kind": "requirement",
      "meaning": "The State application and plan must include an assurance that grant or allotment funds will be used to support activities designed to assist low-income families and individuals (including recipients under TANF/part A of title IV of the Social Security Act, homeless individuals/families, migrant or seasonal farmworkers, and elderly low-income individuals/families), and a description of how such activities will enable them to achieve self-sufficiency, secure and retain meaningful employment, attain adequate education/literacy, make better use of available income, obtain and maintain adequate housing, obtain emergency assistance, and achieve greater participation in community affairs (including grassroots partnerships)."
    },
    {
      "quote_ref": "F026:F028",
      "scope_refs": ["F013", "F014"],
      "kind": "requirement",
      "meaning": "The State application and plan must include an assurance that grant or allotment funds will be used to address youth needs in low-income communities through youth development programs that support the family's primary role, prioritize crime and problem prevention, promote community collaboration, and support innovative community-based youth development programs with demonstrated success in reducing youth crime (such as violence-free zone initiatives and after-school child care programs)."
    },
    {
      "quote_ref": "F029",
      "scope_refs": ["F013", "F014"],
      "kind": "requirement",
      "meaning": "The State application and plan must include an assurance that grant or allotment funds will be used to make more effective use of, and coordinate with, other programs related to the purposes of this chapter, including State welfare reform efforts."
    },
    {
      "quote_ref": "F031",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State application and plan must contain a description of how the State intends to use discretionary funds from the remainder of the grant or allotment described in section 9907(b) of this title in accordance with this chapter, including how the State will support innovative community and neighborhood-based initiatives related to the purposes of this chapter."
    },
    {
      "quote_ref": "F032:F036",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State application and plan must contain information provided by eligible entities in the State, describing the service delivery system for services funded or coordinated under section 9907(a), how linkages will be developed to fill service gaps, how funds will coordinate with other public/private resources, and how the local entity will support innovative community and neighborhood-based initiatives (which may include fatherhood and family-strengthening initiatives)."
    },
    {
      "quote_ref": "F038",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State application and plan must include an assurance that eligible entities in the State will provide, on an emergency basis, supplies, services, nutritious foods, and related services necessary to counteract conditions of starvation and malnutrition among low-income individuals."
    },
    {
      "quote_ref": "F039",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State application and plan must include an assurance that the State and its eligible entities will coordinate and establish linkages between governmental and other social services programs to ensure effective delivery and avoid duplication, and a description of how employment and training activities under WIOA will be coordinated with statewide and local workforce development systems."
    },
    {
      "quote_ref": "F040",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State application and plan must include an assurance that the State will ensure coordination between antipoverty programs in each community, and ensure, where appropriate, that emergency energy crisis intervention programs under the Low-Income Home Energy Assistance Act (title XXVI) are conducted in such community."
    },
    {
      "quote_ref": "F041",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State application and plan must include an assurance that the State will permit and cooperate with Federal investigations undertaken pursuant to section 9916 of this title."
    },
    {
      "quote_ref": "F042",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State application and plan must include an assurance that an eligible entity that received CSBG funding in the previous fiscal year will not have its funding terminated or reduced below its previous proportional share unless, after notice and an opportunity for a hearing on the record, the State determines that cause exists, subject to review by the Secretary under section 9915(b)."
    },
    {
      "quote_ref": "F043",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State application and plan must include an assurance that the State and eligible entities will, to the maximum extent possible, coordinate programs and form partnerships with other organizations serving low-income residents and groups served by the State, including religious, charitable, and community organizations."
    },
    {
      "quote_ref": "F044",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State application and plan must include an assurance that the State will require each eligible entity to establish procedures allowing low-income individuals, community organizations, religious organizations, or representatives of low-income individuals who consider themselves inadequately represented on the governing board or mechanism to petition for adequate representation."
    },
    {
      "quote_ref": "F045",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State application and plan must include an assurance that the State will secure from each eligible entity, as a condition of receiving CSBG funding, a community action plan (submitted to the Secretary upon request with the State plan) containing a community-needs assessment for the community served, which may be coordinated with assessments conducted for other programs."
    },
    {
      "quote_ref": "F046",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State application and plan must include an assurance that the State and all eligible entities will participate by fiscal year 2001 in ROMA, another performance measure system facilitated by the Secretary under section 9917(b), or an alternative qualifying system, together with a description of outcome measures used to measure entity performance in promoting self-sufficiency, family stability, and community revitalization."
    },
    {
      "quote_ref": "F047",
      "scope_refs": ["F013"],
      "kind": "requirement",
      "meaning": "The State application and plan must contain information describing how the State will carry out each of the assurances set forth in subsection (b)."
    },
    {
      "quote_ref": "F050:F054",
      "scope_refs": ["F049"],
      "kind": "definition",
      "meaning": "For purposes of a determination under subsection (b)(8) regarding a funding reduction, the term 'cause' includes a statewide redistribution of CSBG funds to respond to the results of the most recent census or other data, the designation of a new eligible entity, or severe economic dislocation."
    },
    {
      "quote_ref": "F055",
      "scope_refs": ["F049", "F050"],
      "kind": "definition",
      "meaning": "For purposes of a determination under subsection (b)(8) regarding a funding reduction, the term 'cause' includes the failure of an eligible entity to comply with the terms of an agreement or State plan, or to meet a State requirement, as described in section 9915(a) of this title."
    },
    {
      "quote_ref": "F057",
      "scope_refs": ["F049"],
      "kind": "definition",
      "meaning": "For purposes of a determination under subsection (b)(8) regarding a funding termination, the term 'cause' includes the failure of an eligible entity to comply with the terms of an agreement or State plan, or to meet a State requirement, as described in section 9915(a) of this title."
    },
    {
      "quote_ref": "F060",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "The Secretary may prescribe procedures for the purpose of assessing the effectiveness of eligible entities in carrying out the purposes of this chapter."
    },
    {
      "quote_ref": "F064",
      "scope_refs": [],
      "kind": "permission",
      "meaning": "The chief executive officer of each State may revise any State plan prepared under section 9908."
    },
    {
      "quote_ref": "F064",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "If a State plan prepared under this section is revised by the chief executive officer, the State must submit the revised plan to the Secretary."
    },
    {
      "quote_ref": "F067",
      "scope_refs": [],
      "kind": "requirement",
      "meaning": "Each plan or revised plan prepared under this section must be made available for public inspection within the State in a manner that will facilitate public review and comment."
    },
    {
      "quote_ref": "F070",
      "scope_refs": [],
      "kind": "exception",
      "meaning": "For fiscal year 2000, to be eligible to receive a grant or allotment under section 9905 or 9906 of this title, a State was required to prepare and submit an application and State plan under the provisions of the chapter in effect on the day before October 27, 1998, rather than under the provisions of subsections (a) through (c)."
    }
  ]
}
